function ivField(string $name,string $label,mixed $value='',string $type='text',array $options=[],bool $required=false,bool $native=false):void{
 static $n=0;$id='iv-field-'.(++$n);$value=is_scalar($value)?(string)$value:''; ?>
 <label for="<?= $id ?>"><?= e($label) ?><?= $required?' *':'' ?>
 <?php if($type==='select'): ?><select class="form-control" id="<?= $id ?>" name="<?= e($name) ?>" <?= $required?'required':'' ?> <?= $native?'data-select-native':((count($options)>6||str_contains($label,'Mitglied')||str_contains($label,'Eigentümer'))?'data-iv-searchable':'') ?>><?php foreach($options as $key=>$text): ?><option value="<?= e($key) ?>" <?= (string)$key===$value?'selected':'' ?>><?= e($text) ?></option><?php endforeach ?></select>
 <?php elseif($type==='textarea'): ?><textarea class="form-control" id="<?= $id ?>" name="<?= e($name) ?>" rows="3" maxlength="4000" <?= $required?'required':'' ?>><?= e($value) ?></textarea>
 <?php else: ?><input class="form-control" <?= in_array($name,['category','data[category]','common[category]'],true)?'list="inventory-categories"':'' ?> id="<?= $id ?>" name="<?= e($name) ?>" type="<?= e($type) ?>" value="<?= e($value) ?>" <?= $type==='number'?'min="'.($name==='data[content_quantity]'?'1':'0').'" max="1000000" step="1"':'maxlength="200"' ?> <?= $required?'required':'' ?>><?php endif ?></label><?php
}
function ivPost(string $action,string $target='',int $version=0):string{$restore=(input($_POST,'action')==='inventory-'.$action||($action==='reserve'&&in_array(input($_POST,'action'),['inventory-loan-draft','inventory-loan-stock-browse','inventory-window-check'],true))||(input($_POST,'action')==='inventory-source-browse'&&(($action==='item'&&input($_POST,'source_form','item')==='item')||($action==='individuals'&&input($_POST,'source_form')==='individual'))))&&input($_POST,'target')===$target;return csrf().hidden('action','inventory-'.$action).hidden('target',$target).hidden('version',$restore?input($_POST,'version'):$version).hidden('request_key',$restore?input($_POST,'request_key'):bin2hex(random_bytes(16)));}
function ivExport(string $kind,array $filters=[],?callable $text=null):void{ ?><form method="post" class="iv-no-print"><?= csrf().hidden('action','inventory-export').hidden('export_kind',$kind) ?><?php foreach($filters as $k=>$v)echo hidden($k,$v); ?><button class="btn btn-outline theme-secondary secondary"><?= icon('download') ?> <?= e($text?$text('CSV exportieren'):'CSV exportieren') ?></button></form><?php }
function ivWhereTable(array $rows,\Kulturhus\Verein\ActorNames $ivActorNames,bool $links=true,?callable $text=null):void{
 $text??=static function(string $source,array $values=[]):string{$replace=[];foreach($values as$name=>$value)$replace['{'.$name.'}']=(string)$value;return strtr($source,$replace);}; ?>
<div class="table-scroll"><table class="table iv-where"><thead><tr><?php foreach(['Gegenstand','Menge','Aktueller Ort / Aufbewahrung','Status','Zuletzt bestätigt']as$label): ?><th><?= e($text($label)) ?></th><?php endforeach ?></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><?php if($links): ?><a href="<?= e(url(['view'=>'inventory','tab'=>'items','item'=>$r['item_id']])) ?>"><strong><?= e($r['item_name']) ?></strong></a><?php else: ?><strong><?= e($r['item_name']) ?></strong><?php endif ?><small><?= e($r['code']) ?><?= e($r['responsible_name']!==null&&$r['responsible_name']!==''?$text(' · Zuständig: {name}',['name'=>$r['responsible_name']]):'') ?></small></td><td><?= e(Inventory::contentSummary($r,(int)$r['quantity'],$text)?:$r['quantity'].' '.$r['unit']) ?></td><td><strong><?= e($r['location_name']!==null&&$r['location_name']!==''?$r['location_name']:$text('Standort nicht bestätigt')) ?></strong><small><?= e(implode(' · ',array_filter([$r['building'],$r['room'],$r['location_shelf']],static fn($value)=>$value!==null&&$value!==''))) ?></small><?php if($r['holder_name']!==null&&$r['holder_name']!==''): ?><small><?= e($r['holder_name']) ?></small><?php endif ?></td><td><span class="status <?= $r['state']==='available'?'aktiv':'passiv' ?>"><?= e($text(['available'=>'Verfügbar','reserved'=>'Reserviert','blocked'=>'Gesperrt / Wartung','issued'=>'Ausgeliehen'][$r['state']])) ?></span><?php if($r['loan_id']): ?><small><a href="<?= e(url(['view'=>'inventory','tab'=>'loans','loan'=>$r['loan_id']])) ?>"><?= e($text('Rückgabe: {date} →',['date'=>dateDe($r['due_on'])])) ?></a></small><small><?= e($r['purpose']) ?></small><?php endif ?></td><td><?= e($r['confirmed_at']?(new DateTimeImmutable($r['confirmed_at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i'):$text('Noch nicht bestätigt')) ?><small><?= e($ivActorNames->label($r['confirmed_by']??null,$text)) ?></small></td></tr><?php endforeach ?>
<?php if(!$rows): ?><tr><td colspan="5" class="empty-state"><?= e($text('Keine Bestände für diese Auswahl.')) ?></td></tr><?php endif ?></tbody></table></div><?php }
?>
